-- ==========================================================================================
-- ANSI-SQL-92 compliant schema for TierFourConnectivity
-- Generated by CIMTool https://cimtool.ucaiug.io
-- 
-- Compound types are represented as separate 1:1 tables and enforces via
-- a combination of the use of both UNIQUE on columns that reference tables
-- representing Compound types and corresponding FK column constraint
-- definitions to those tables.
-- 
-- Though Compounds do not have an "mRID" and do not inherantly represent
-- persistent objects in the CIM (i.e. are inherited from IdentifiedObject)
-- they are here given a unique identifier "id" that is distinct from "mRID"
-- and used for persistence purposes.
-- 
-- Tables that represent Compound types in the CIM are not normalized for
-- the following reasons:
-- 
--   Normalization, particularly to 3NF, typically requires:
--     No repeating groups.
--     No partial or transitive dependencies.
--     Every non-key attribute must depend only on the whole key.
--     
--   But compound classes in the CIM domain:
--     Do not have surrogate or natural primary keys derived from business rules.
--     Are logically value objects: any change to any attribute means the value is distinct.
--     Have implicit semantic atomicity — they’re treated as indivisible chunks.
--     
-- ==========================================================================================
--

-- An electrical connection point (AC or DC) to a piece of conducting equipment.
-- Terminals are connected at physical connection points called connectivity
-- nodes.
CREATE TABLE "ACDCTerminal"
(
    "mRID" VARCHAR(100) PRIMARY KEY,
    -- The orientation of the terminal connections for a multiple terminal conducting
    -- equipment. The sequence numbering starts with 1 and additional terminals
    -- should follow in increasing order. The first terminal is the "starting
    -- point" for a two terminal branch.
    "sequenceNumber" INTEGER
);

-- A line segment is a conductor or combination of conductors, with consistent
-- electrical characteristics along its length, building a single electrical
-- system that carries alternating current between two points in the power
-- system.
-- The BaseVoltage at the two ends of a line segment shall have the same BaseVoltage.nominalVoltage.
-- However, boundary lines may have slightly different BaseVoltage.nominalVoltages
-- and variation is allowed. Larger voltage difference in general requires
-- use of an equivalent branch.
-- Line segment impedances can be either directly described in electrical
-- terms or physical line detail can be provided from which impedances can
-- be calculated.
-- <b>Directly described impedances</b>
-- For symmetrical, transposed three phase line segments, it is sufficient
-- to use attributes of the line segment, which describe impedances and admittances
-- for the entire length of the line segment. Additionally, line segment impedances
-- can be computed by using line segment length and associated per length
-- impedances.
-- Unbalanced modeling of impedances is supported by the per length phase
-- impedance matrix (PerLengthPhaseImpedance) in conjunction with phase-to-sequence
-- number mapping supplied by either ACLineSegmentPhase or WirePosition. The
-- sequence numbers are referenced by the row and column attributes of the
-- per length phase impedance matrix. This method enables single-phase and
-- two-phase line segments, and transpositions of phases, to be described
-- using the same per length phase impedance matrix. The length of the line
-- segment is used in the computation of total impedance values for the line
-- segment.
-- <b>Line detail characteristics</b>
-- There are three approaches to providing line detail and all use WireAssembly
-- to supply line positions:
-- <ul>
-- <li>Option 1 - WireAssembly supplies only line positions. ACLineSegmentPhase
-- points to wire type and intraphase spacing and supplies the phase-to-sequence
-- number mapping.</li>
-- <li>Option 2 - WireAssembly supplies line position and, for each position,
-- also supplies wire type and intraphase spacing. ACLineSegmentPhase supplies
-- the phase-to-sequence number mapping.</li>
-- <li>Option 3 - WireAssembly supplies line position and, for each position,
-- also supplies wire type and intraphase spacing and phase. WireAssembly
-- therefore supplies the phase-to-sequence number mapping and ACLineSegmentPhase
-- is not needed.</li>
-- </ul>
CREATE TABLE "ACLineSegment"
(
    "mRID" VARCHAR(100) PRIMARY KEY,
    -- The ordering of adjacent ACLineSegments within a MultiCircuitGroup. The
    -- circuit numbering starts with 1 and additional lines should follow in increasing
    -- order.
    -- The circuitNumber of the ACLineSegment within a MultiCircuitGroup (e.g.
    -- adjacent towers in the same corridor) need not match the circuitNumber
    -- of the ConductorPosition in an XYSpacing.
    "circuitNumber" INTEGER,
    -- The MultiCircuitGroup to which the ACLineSegment belongs
    -- FK column reference to table representing the "MultiCircuitGroup" class
    "MultiCircuitGroup" VARCHAR(100)
);

-- A line segment phase represents one phase (or optionally the neutral) of
-- an alternating current line segment.
-- Under most circumstances there is not a line segment phase for the neutral.
-- However, if a wire assembly is being used and it does not specify phase,
-- a line segment phase must exist for each position in the assembly (including
-- the neutral).
CREATE TABLE "ACLineSegmentPhase"
(
    "mRID" VARCHAR(100) PRIMARY KEY,
    -- Phase identifies the phase or neutral connection of the conductor at both
    -- ends.
    -- FK column reference to table representing the "SinglePhaseKind" enumeration
    "phase" VARCHAR(100),
    -- Sequence number provides the numbering for this line segment phase. When
    -- impedance is directly described, sequence number binds the phase to the
    -- column and row for entries in the per length phase impedance matrix (PhaseImpedanceData
    -- of PerLengthPhaseImpedance). When used in conjunction with a wire assembly
    -- description, sequence number associates the line segment phase to a position.
    -- For a line segment not a part of a parallel line segment group, sequence
    -- number starts at one and increments by one through each line segment phase
    -- associated with the line segment. If there is a line segment phase for
    -- neutral, it is numbered last.
    "sequenceNumber" INTEGER,
    -- The line segment to which the phase belongs.
    -- FK column reference to table representing the "ACLineSegment" class
    "ACLineSegment" VARCHAR(100),
    -- The MultiCircuitGroup to which the shared phase belongs
    -- FK column reference to table representing the "MultiCircuitGroup" class
    "MultiCircuitGroup" VARCHAR(100)
);

-- An overhead switch utilizing a mechanical linkage to provide a visible
-- airgap for feeder sectionalizing and isolation of substation equipment.
-- Depending on its design configuration, it can either feature interrupter
-- attachments to break load current or serve purely as a non-loadbreak isolation
-- point.
CREATE TABLE "AirBreakSwitch"
(
    "mRID" VARCHAR(100) PRIMARY KEY
);

CREATE TABLE "AreaConfiguration"
(
    "mRID" VARCHAR(100) PRIMARY KEY
);

-- A rotating machine whose shaft rotates asynchronously with the electrical
-- field. Also known as an induction machine with no external connection to
-- the rotor windings, e.g. squirrel-cage induction machine.
CREATE TABLE "AsynchronousMachine"
(
    "mRID" VARCHAR(100) PRIMARY KEY,
    -- Indicates the type of Asynchronous Machine (motor or generator).
    -- FK column reference to table representing the "AsynchronousMachineKind" enumeration
    "asynchronousMachineType" VARCHAR(100)
);

-- Kind of Asynchronous Machine.
CREATE TABLE "AsynchronousMachineKind" ( "name" VARCHAR(100) UNIQUE );
-- The Asynchronous Machine is a generator.
INSERT INTO "AsynchronousMachineKind" ( "name" ) VALUES ( 'generator' );
-- The Asynchronous Machine is a motor.
INSERT INTO "AsynchronousMachineKind" ( "name" ) VALUES ( 'motor' );

-- Defines a system base voltage which is referenced. This may be different
-- than the rated voltage.
CREATE TABLE "BaseVoltage"
(
    "mRID" VARCHAR(100) PRIMARY KEY,
    -- The power system resource's base voltage, expressed on a phase-to-phase
    -- (line-to-line) basis. Shall be a positive value and not zero.
    "nominalVoltage" DOUBLE PRECISION
);

-- A mechanical switching device capable of making, carrying, and breaking
-- currents under normal circuit conditions and also making, carrying for
-- a specified time, and breaking currents under specified abnormal circuit
-- conditions e.g. those of short circuit.
CREATE TABLE "Breaker"
(
    "mRID" VARCHAR(100) PRIMARY KEY
);

-- A four-terminal switching device used to bypass voltage regulators, reclosers,
-- and other distribution devices by creating a physical airgap to the device
-- and alternate current path.
CREATE TABLE "BypassSwitch"
(
    "mRID" VARCHAR(100) PRIMARY KEY
);

-- A Clamp is a galvanic connection at a line segment where other equipment
-- is connected. A Clamp does not cut the line segment.
-- A Clamp is ConductingEquipment and has one Terminal with an associated
-- ConnectivityNode. Any other ConductingEquipment can be connected to the
-- Clamp ConnectivityNode.
CREATE TABLE "Clamp"
(
    "mRID" VARCHAR(100) PRIMARY KEY
);

-- Enumeration to allow designation of a compensator as either a capacitor
-- or reactor.
-- In previous versions of CIM, this was denoted by sign convention of b or
-- x.
CREATE TABLE "CompensatorKind" ( "name" VARCHAR(100) UNIQUE );
-- capacitor
INSERT INTO "CompensatorKind" ( "name" ) VALUES ( 'capacitor' );
-- reactor
INSERT INTO "CompensatorKind" ( "name" ) VALUES ( 'reactor' );

-- The parts of the AC power system that are designed to carry current or
-- that are conductively connected through terminals.
CREATE TABLE "ConductingEquipment"
(
    "mRID" VARCHAR(100) PRIMARY KEY,
    -- Base voltage of this conducting equipment. Use only when there is no voltage
    -- level container used and only one base voltage applies. For example, not
    -- used for transformers.
    -- FK column reference to table representing the "BaseVoltage" class
    "BaseVoltage" VARCHAR(100)
);

-- Combination of conducting material with consistent electrical characteristics,
-- building a single electrical system, used to carry current between points
-- in the power system.
CREATE TABLE "Conductor"
(
    "mRID" VARCHAR(100) PRIMARY KEY,
    -- Segment length for calculating line segment capabilities.
    "length" DOUBLE PRECISION
);

-- A persistent connectivity-based containment of Equipment with clearly defined
-- electrical boundaries based on terminals of boundary equipment in a transmission
-- or distribution network.
-- In a transmission context, this class provides a persistent superset grouping
-- of equipment across multiple substations to describe an operating area
-- of responsibility or bounded area for simulation studies.
-- In a distribution context, this class differs from Feeder (which is largely
-- for naming purposes) by providing groupings of equipment on the basis of
-- connectivity.
CREATE TABLE "ConnectedArea"
(
    "mRID" VARCHAR(100) PRIMARY KEY,
    -- Specifies the type of connectivity area
    -- FK column reference to table representing the "ConnectedAreaKind" enumeration
    "kind" VARCHAR(100),
    "otherKind" VARCHAR(255),
    -- Used between ConnectedAreas of the same kind to denote upstream / downstram
    -- FK column reference to table representing the "ConnectedArea" class
    "AdjacentArea" VARCHAR(100),
    -- FK column reference to table representing the "AreaConfiguration" class
    "AreaConfiguration" VARCHAR(100),
    -- The larger superset area within which the given connectivity area is contained
    -- (e.g. distribution area that contains a feeder area)
    -- FK column reference to table representing the "ConnectedArea" class
    "ContainedWithin" VARCHAR(100)
);

CREATE TABLE "ConnectedAreaKind" ( "name" VARCHAR(100) UNIQUE );
-- A topologically continuous grouping of distribution feeders, typically
-- divided by normal-open switches. The DistributionArea provides the highest-level
-- description of the equipment controlled by the Distribution System Operator
-- (DSO)
INSERT INTO "ConnectedAreaKind" ( "name" ) VALUES ( 'distributionArea' );
-- The FeederArea contains all medium voltage equipment not contained in a
-- SwitchArea or Substation / Bay. It also includes all Sectionalisers, Reclosers,
-- and all other poletop and pad-mounted switchgear that form the boundary
