INSERT INTO "ConnectedAreaKind" ( "name" ) VALUES ( 'feederArea' );
-- Containment of distribution equipment that 1) has clearly-defined electrical
-- boundaries formed by one or more point of common coupling Switch objects
-- and 2) that acts as a single controllable entity which can be operated
-- in grid-connected or islanded mode. This covers both utility-owned distribution
-- microgrids and customer-owned facility microgrids as defined in IEV 617-04-22.
INSERT INTO "ConnectedAreaKind" ( "name" ) VALUES ( 'microgrid' );
INSERT INTO "ConnectedAreaKind" ( "name" ) VALUES ( 'other' );
INSERT INTO "ConnectedAreaKind" ( "name" ) VALUES ( 'plant' );
-- Containment of low-voltage distribution Equipment and customer-owned Equipment
-- with clearly defined electrical boundaries formed by the low-side terminal(s)
-- of one or more PowerTransformer objects.
INSERT INTO "ConnectedAreaKind" ( "name" ) VALUES ( 'secondaryArea' );
INSERT INTO "ConnectedAreaKind" ( "name" ) VALUES ( 'subtransmissionArea' );
-- Containment of medium-voltage distribution Equipment with clearly defined
-- electrical boundaries formed by one or more Switch objects. The SwitchArea
-- contains all conductors, fuses, poletop equipment, and vault equipment.
-- It also contains all secondary service transformers not contained in a
-- SecondarySubstation.
INSERT INTO "ConnectedAreaKind" ( "name" ) VALUES ( 'switchArea' );
-- The connectivity-based grouping of equipment forming a transmission system
