    -- the Name class as aliasName is planned for retirement at a future time.
    "aliasName" VARCHAR(255),
    -- The description is a free human readable text describing or naming the
    -- object. It may be non unique and may not correlate to a naming hierarchy.
    "description" VARCHAR(255),
    -- The name is any free human readable and possibly non unique text naming
    -- the object.
    "name" VARCHAR(255)
);

-- A short section of conductor with negligible impedance which can be manually
-- removed and replaced if the circuit is de-energized. Note that zero-impedance
-- branches can potentially be modelled by other equipment types.
CREATE TABLE "Jumper"
(
    "mRID" VARCHAR(100) PRIMARY KEY
);

-- A linear shunt compensator has banks or sections with equal admittance
-- values.
CREATE TABLE "LinearShuntCompensator"
(
    "mRID" VARCHAR(100) PRIMARY KEY
);

-- A per phase linear shunt compensator has banks or sections with equal admittance
-- values.
CREATE TABLE "LinearShuntCompensatorPhase"
(
    "mRID" VARCHAR(100) PRIMARY KEY
);

-- A mechanical switching device capable of making, carrying, and breaking
-- currents under normal operating conditions.
CREATE TABLE "LoadBreakSwitch"
(
    "mRID" VARCHAR(100) PRIMARY KEY
);

-- Aggregates a set of line segments that are on the same tower, or in the
-- same right-of-way, close enough that mutual coupling impedances between
-- the lines need to be included in network analysis.
CREATE TABLE "MultiCircuitGroup"
(
    "mRID" VARCHAR(100) PRIMARY KEY,
    "reversedSequenceNumber" INTEGER NOT NULL DEFAULT 1 CHECK ("reversedSequenceNumber" IN (0, 1)),
    -- FK column reference to table representing the "Terminal" class
    "ReferenceTerminal" VARCHAR(100)
);

-- Enumeration of phase identifiers used to designate the combination of phase
-- and/or neutral conductors at a terminal, measurement or equipment modelled
-- as a single-line balanced equivalent.
-- This is an unordered enumeration of phase identifiers. Allows designation
-- of phases for both transmission and distribution equipment, circuits and
-- loads. The enumeration, by itself, does not describe how the phases are
-- connected together or connected to ground. Ground is not explicitly denoted
-- as a phase.
-- Residential and small commercial loads are often served from single-phase,
-- or split-phase, secondary circuits. For the example of s12N, phases 1 and
-- 2 refer to hot wires that are 180 degrees out of phase, while N refers
-- to the neutral wire. Through single-phase transformer connections, these
-- secondary circuits may be served from one or two of the primary phases
-- A, B, and C. For three-phase loads, use the A, B, C phase codes instead
-- of s12N.
-- The integer values are from IEC 61968-9 to support revenue metering applications.
CREATE TABLE "PhaseCode" ( "name" VARCHAR(100) UNIQUE );
-- Phase A.
INSERT INTO "PhaseCode" ( "name" ) VALUES ( 'A' );
-- Phases A and B.
INSERT INTO "PhaseCode" ( "name" ) VALUES ( 'AB' );
-- Phases A, B, and C.
INSERT INTO "PhaseCode" ( "name" ) VALUES ( 'ABC' );
-- Phases A, B, C, and N.
INSERT INTO "PhaseCode" ( "name" ) VALUES ( 'ABCN' );
-- Phases A, B, and neutral.
INSERT INTO "PhaseCode" ( "name" ) VALUES ( 'ABN' );
-- Phases A and C.
INSERT INTO "PhaseCode" ( "name" ) VALUES ( 'AC' );
-- Phases A, C and neutral.
INSERT INTO "PhaseCode" ( "name" ) VALUES ( 'ACN' );
-- Phases A and neutral.
INSERT INTO "PhaseCode" ( "name" ) VALUES ( 'AN' );
-- Phase B.
INSERT INTO "PhaseCode" ( "name" ) VALUES ( 'B' );
-- Phases B and C.
INSERT INTO "PhaseCode" ( "name" ) VALUES ( 'BC' );
-- Phases B, C, and neutral.
INSERT INTO "PhaseCode" ( "name" ) VALUES ( 'BCN' );
-- Phases B and neutral.
INSERT INTO "PhaseCode" ( "name" ) VALUES ( 'BN' );
-- Phase C.
INSERT INTO "PhaseCode" ( "name" ) VALUES ( 'C' );
-- Phases C and neutral.
INSERT INTO "PhaseCode" ( "name" ) VALUES ( 'CN' );
-- Neutral phase.
INSERT INTO "PhaseCode" ( "name" ) VALUES ( 'N' );
-- Unknown non-neutral phase.
INSERT INTO "PhaseCode" ( "name" ) VALUES ( 'X' );
-- Unknown non-neutral phase plus neutral.
INSERT INTO "PhaseCode" ( "name" ) VALUES ( 'XN' );
-- Two unknown non-neutral phases.
INSERT INTO "PhaseCode" ( "name" ) VALUES ( 'XY' );
-- Two unknown non-neutral phases plus neutral.
INSERT INTO "PhaseCode" ( "name" ) VALUES ( 'XYN' );
-- No phases specified.
INSERT INTO "PhaseCode" ( "name" ) VALUES ( 'none' );
-- Secondary phase 1.
INSERT INTO "PhaseCode" ( "name" ) VALUES ( 's1' );
-- Secondary phase 1 and 2.
INSERT INTO "PhaseCode" ( "name" ) VALUES ( 's12' );
-- Secondary phases 1, 2, and neutral.
INSERT INTO "PhaseCode" ( "name" ) VALUES ( 's12N' );
-- Secondary phase 1 and neutral.
INSERT INTO "PhaseCode" ( "name" ) VALUES ( 's1N' );
-- Secondary phase 2.
INSERT INTO "PhaseCode" ( "name" ) VALUES ( 's2' );
-- Secondary phase 2 and neutral.
INSERT INTO "PhaseCode" ( "name" ) VALUES ( 's2N' );

-- The configuration of phase connections for a single terminal device such
-- as a load or capacitor.
CREATE TABLE "PhaseShuntConnectionKind" ( "name" VARCHAR(100) UNIQUE );
-- Delta connection.
INSERT INTO "PhaseShuntConnectionKind" ( "name" ) VALUES ( 'D' );
-- Ground connection; use when explicit connection to ground needs to be expressed
-- in combination with the phase code, such as for electrical wire/cable or
-- for meters.
INSERT INTO "PhaseShuntConnectionKind" ( "name" ) VALUES ( 'G' );
-- Independent winding, for single-phase connections.
INSERT INTO "PhaseShuntConnectionKind" ( "name" ) VALUES ( 'I' );
-- Wye connection.
INSERT INTO "PhaseShuntConnectionKind" ( "name" ) VALUES ( 'Y' );
-- Wye, with neutral brought out for grounding.
INSERT INTO "PhaseShuntConnectionKind" ( "name" ) VALUES ( 'Yn' );

-- A transformer phase shifting tap model that controls the phase angle difference
