CREATE TABLE "PhaseTapChanger"
(
    "mRID" VARCHAR(100) PRIMARY KEY,
    -- Transformer end to which this phase tap changer belongs.
    -- FK column reference to table representing the "TransformerEnd" class
    "TransformerEnd" VARCHAR(100)
);

-- A connection to the AC network for energy production or consumption that
-- uses power electronics rather than rotating machines.
CREATE TABLE "PowerElectronicsConnection"
(
    "mRID" VARCHAR(100) PRIMARY KEY
);

-- A single phase of a power electronics connection.
CREATE TABLE "PowerElectronicsConnectionPhase"
(
    "mRID" VARCHAR(100) PRIMARY KEY,
    -- Phase of this energy producer component. If the energy producer is wye
    -- connected, the connection is from the indicated phase to the central ground
    -- or neutral point. If the energy producer is delta connected, the phase
    -- indicates an energy producer connected from the indicated phase to the
    -- next logical non-neutral phase.
    -- FK column reference to table representing the "SinglePhaseKind" enumeration
    "phase" VARCHAR(100),
    -- FK column reference to table representing the "PhaseCode" enumeration
    "phases" VARCHAR(100),
    -- Power electronics connection of this power electronics connection phase.
    -- FK column reference to table representing the "PowerElectronicsConnection" class
    "PowerElectronicsConnection" VARCHAR(100)
);

-- A power system resource (PSR) can be an item of equipment such as a switch,
-- an equipment container containing many individual items of equipment such
-- as a substation, or an organisational entity such as sub-control area.
-- Power system resources can have measurements associated.
CREATE TABLE "PowerSystemResource"
(
    "mRID" VARCHAR(100) PRIMARY KEY
);

-- An electrical device consisting of two or more coupled windings, with or
-- without a magnetic core, for introducing mutual coupling between electric
-- circuits. Transformers can be used to control voltage and phase shift (active
-- power flow).
-- A power transformer may be composed of separate transformer tanks that
-- need not be identical.
-- A power transformer can be modelled with or without tanks and is intended
-- for use in both balanced and unbalanced representations. A power transformer
-- typically has two terminals, but may have one (grounding), three or more
-- terminals.
-- The inherited association ConductingEquipment.BaseVoltage should not be
-- used. The association from TransformerEnd to BaseVoltage should be used
-- instead.
CREATE TABLE "PowerTransformer"
(
    "mRID" VARCHAR(100) PRIMARY KEY,
    -- Vector group of the transformer for protective relaying, e.g., Dyn1. For
    -- unbalanced transformers, this may not be simply determined from the constituent
    -- winding connections and phase angle displacements.
    -- The vectorGroup string consists of the following components in the order
    -- listed: high voltage winding connection, mid voltage winding connection
    -- (for three winding transformers), phase displacement clock number from
    -- 0 to 11, low voltage winding connection
    -- phase displacement clock number from 0 to 11. The winding connections are
    -- D (delta), Y (wye), YN (wye with neutral), Z (zigzag), ZN (zigzag with
    -- neutral), A (auto transformer). Upper case means the high voltage, lower
    -- case mid or low. The high voltage winding always has clock position 0 and
    -- is not included in the vector group string. Some examples: YNy0 (two winding
    -- wye to wye with no phase displacement), YNd11 (two winding wye to delta
    -- with 330 degrees phase displacement), YNyn0d5 (three winding transformer
    -- wye with neutral high voltage, wye with neutral mid voltage and no phase
    -- displacement, delta low voltage with 150 degrees displacement).
    -- Phase displacement is defined as the angular difference between the phasors
    -- representing the voltages between the neutral point (real or imaginary)
    -- and the corresponding terminals of two windings, a positive sequence voltage
    -- system being applied to the high-voltage terminals, following each other
    -- in alphabetical sequence if they are lettered, or in numerical sequence
    -- if they are numbered: the phasors are assumed to rotate in a counter-clockwise
    -- sense.
    "vectorGroup" VARCHAR(255)
);

-- It represents one side of a power transformer within the power system analysis
-- models and is associated with a terminal.
-- For sequence-domain balanced modeling of two-winding and three-winding
-- transformers, the series impedance and shunt admittance values of a star
-- equivalent may be specified as follows:
-- 1) A two-winding power transformer has two power transformer ends even
-- if both sides have the same rated voltage. The series impedance and shunt
-- admittance are specified on the power transformer end with end number=1.
-- The power transformer end with end number=2 shall have zero impedance values.
-- 2) A three-winding power transformer has three power transformer ends with
-- the series impedance assigned to each end using a mesh to star conversion.
-- The shunt admittance may be specified on the transformer core, distributed
-- on the power transformer ends, or lumped onto one power transformer end.
-- The preferred method is lumped onto the end with end number=1.
-- Transformers with more than three windings use one power transformer end
-- per winding and specify series impedance pairwise across windings using
-- a mesh model. The shunt admittance may be specified on the transformer
-- core, distributed on the power transformer ends, or lumped onto one power
-- transformer end.
CREATE TABLE "PowerTransformerEnd"
(
    "mRID" VARCHAR(100) PRIMARY KEY,
    -- Kind of connection.
    -- FK column reference to table representing the "WindingConnection" enumeration
    "connectionKind" VARCHAR(100),
    -- Denotes the individual winding configuration (e.g. D1). The configuration
    -- kind and the connection kind (e.g. Yn) of each winding are assembled to
    -- form the vector group of the power transformer (e.g. YNyn6), as defined
    -- in in IEC 60076-1 / IEEE c57.12.70-2021.
    -- This attribute replaces the phaseAngleClock.
    -- FK column reference to table representing the "WindingConfigurationKind" enumeration
    "windingConfiguration" VARCHAR(100),
    -- The power transformer of this power transformer end.
    -- FK column reference to table representing the "PowerTransformer" class
    "PowerTransformer" VARCHAR(100)
);

-- A ProtectedSwitch is a switching device that can be operated by ProtectionEquipment.
CREATE TABLE "ProtectedSwitch"
(
    "mRID" VARCHAR(100) PRIMARY KEY
);

-- A tap changer that changes the voltage ratio impacting the voltage magnitude
-- but not the phase angle across the transformer.
-- Angle sign convention (general): Positive value indicates a positive phase
-- shift from the winding where the tap is located to the other winding (for
-- a two-winding transformer).
CREATE TABLE "RatioTapChanger"
(
    "mRID" VARCHAR(100) PRIMARY KEY,
    -- The transformer end for this additional ratio tap changer.
    -- FK column reference to table representing the "TransformerEnd" class
    "TransformerEnd" VARCHAR(100)
);

-- Pole-mounted fault interrupter with built-in phase and ground relays, current
-- transformer (CT), and supplemental controls.
CREATE TABLE "Recloser"
(
    "mRID" VARCHAR(100) PRIMARY KEY
);

-- A type of conducting equipment that can regulate a quantity (i.e. voltage
-- or flow) at a specific point in the network.
CREATE TABLE "RegulatingCondEq"
(
    "mRID" VARCHAR(100) PRIMARY KEY
);

-- A rotating machine which may be used as a generator or motor.
CREATE TABLE "RotatingMachine"
(
    "mRID" VARCHAR(100) PRIMARY KEY,
    -- FK column reference to table representing the "RotatingMachinePhase" class
    "RotatingMachinePhase" VARCHAR(100)
);

-- Represents a single-phase motor or generator. The specifics of the RotatingMachinePhase
-- (e.g. type) are determined by the associated asynchronous or synchronous
-- machine along with the specific generating unit associated to the rotating
-- machine.
CREATE TABLE "RotatingMachinePhase"
(
    "mRID" VARCHAR(100) PRIMARY KEY,
    -- FK column reference to table representing the "SinglePhaseKind" enumeration
    "phase" VARCHAR(100),
    -- FK column reference to table representing the "RotatingMachine" class
    "RotatingMachine" VARCHAR(100)
);

-- Automatic switch that will lock open to isolate a faulted section. It may,
-- or may not, have load breaking capability. Its primary purpose is to provide
-- fault sectionalising at locations where the fault current is either too
-- high, or too low, for proper coordination of fuses.
CREATE TABLE "Sectionaliser"
(
    "mRID" VARCHAR(100) PRIMARY KEY
);

-- A Series Compensator is a series capacitor or reactor or an AC transmission
-- line without charging susceptance. It is a two terminal device.
CREATE TABLE "SeriesCompensator"
(
    "mRID" VARCHAR(100) PRIMARY KEY,
    -- Denotes series capacitor or reactor
    -- FK column reference to table representing the "CompensatorKind" enumeration
    "compensatorType" VARCHAR(100)
);

-- A safety-grade switch mechanism installed at commercial, industrial, or
-- residential facilities to completely cut off incoming electrical service.
-- From an electrical connectivity standpoint, this class models a self-contained
-- unit that physically houses and integrates the electrical meter and meter
-- base alongside the main circuit-breaking or disconnect contacts.
CREATE TABLE "ServiceDisconnect"
(
    "mRID" VARCHAR(100) PRIMARY KEY
);

-- A shunt capacitor or reactor or switchable bank of shunt capacitors or
-- reactors. A section of a shunt compensator is an individual capacitor or
-- reactor. A negative value for bPerSection indicates that the compensator
-- is a reactor. ShuntCompensator is a single terminal device. Ground is implied.
CREATE TABLE "ShuntCompensator"
(
    "mRID" VARCHAR(100) PRIMARY KEY,
    -- Denotes whether shunt capacitor or reactor
    -- FK column reference to table representing the "CompensatorKind" enumeration
    "compensatorType" VARCHAR(100),
    -- Required for Yn and I connections (as represented by ShuntCompensator.phaseConnection).
    -- True if the neutral is solidly grounded.
    "grounded" INTEGER NOT NULL DEFAULT 1 CHECK ("grounded" IN (0, 1)),
    -- The type of phase connection, such as wye or delta.
    -- FK column reference to table representing the "PhaseShuntConnectionKind" enumeration
    "phaseConnection" VARCHAR(100)
);

-- Single phase of a multi-phase shunt compensator when its attributes might
-- be different per phase.
CREATE TABLE "ShuntCompensatorPhase"
(
    "mRID" VARCHAR(100) PRIMARY KEY,
    -- Phase of this shunt compensator component. If the shunt compensator is
    -- wye connected, the connection is from the indicated phase to the central
    -- ground or neutral point. If the shunt compensator is delta connected, the
    -- phase indicates a shunt compensator connected from the indicated phase
    -- to the next logical non-neutral phase.
    -- FK column reference to table representing the "SinglePhaseKind" enumeration
    "phase" VARCHAR(100),
    -- FK column reference to table representing the "PhaseCode" enumeration
    "phases" VARCHAR(100),
    -- Shunt compensator of this shunt compensator phase.
    -- FK column reference to table representing the "ShuntCompensator" class
    "ShuntCompensator" VARCHAR(100)
);

-- Enumeration of phase identifiers used to designate the specific phase of
-- conducting equipment modelled as individual unbalanced phases.
-- Allows designation of specific phases for transmission and distribution
-- equipment, circuits and loads.
CREATE TABLE "SinglePhaseKind" ( "name" VARCHAR(100) UNIQUE );
-- Phase A.
INSERT INTO "SinglePhaseKind" ( "name" ) VALUES ( 'A' );
-- Phase B.
INSERT INTO "SinglePhaseKind" ( "name" ) VALUES ( 'B' );
-- Phase C.
INSERT INTO "SinglePhaseKind" ( "name" ) VALUES ( 'C' );
-- Earth. Denotes physical earth for conductor spacing or devices connected
-- directly to earth (e.g. earthing reactors, pole ground, single wire earth
-- return).
INSERT INTO "SinglePhaseKind" ( "name" ) VALUES ( 'E' );
-- Neutral.
INSERT INTO "SinglePhaseKind" ( "name" ) VALUES ( 'N' );
-- Unknown. Floating phases or undetermined phasing.
INSERT INTO "SinglePhaseKind" ( "name" ) VALUES ( 'X' );
INSERT INTO "SinglePhaseKind" ( "name" ) VALUES ( 'Y' );
-- Secondary phase 1.
INSERT INTO "SinglePhaseKind" ( "name" ) VALUES ( 's1' );
-- Secondary phase 2.
INSERT INTO "SinglePhaseKind" ( "name" ) VALUES ( 's2' );

-- A subset of a geographical region of a power system network model.
CREATE TABLE "SubGeographicalRegion"
(
    "mRID" VARCHAR(100) PRIMARY KEY,
    -- The geographical region which this sub-geographical region is within.
    -- FK column reference to table representing the "GeographicalRegion" class
    "Region" VARCHAR(100)
);

-- A collection of equipment for purposes other than generation or utilization,
-- through which electric energy in bulk is passed for the purposes of switching
-- or modifying its characteristics.
CREATE TABLE "Substation"
(
    "mRID" VARCHAR(100) PRIMARY KEY,
    -- The SubGeographicalRegion containing the substation.
    -- FK column reference to table representing the "SubGeographicalRegion" class
    "Region" VARCHAR(100)
);

-- A generic device designed to close, or open, or both, one or more electric
-- circuits. All switches are two terminal devices including grounding switches.
-- The ACDCTerminal.connected at the two sides of the switch shall not be
-- considered for assessing switch connectivity, i.e. only Switch.open, .normalOpen
-- and .locked are relevant.
CREATE TABLE "Switch"
(
    "mRID" VARCHAR(100) PRIMARY KEY,
    -- Explicitly marks a switch as boundary as an input flag for topology processing
    -- of ConnectedAreas
    "areaBoundary" INTEGER NOT NULL DEFAULT 1 CHECK ("areaBoundary" IN (0, 1)),
    -- Indicates whether the phases of the switch are mechanically linked together
    -- or can be operated separately
    "gangOperated" INTEGER NOT NULL DEFAULT 1 CHECK ("gangOperated" IN (0, 1)),
    -- The attribute is used in cases when no Measurement for the status value
    -- is present. If the Switch has a status measurement the Discrete.normalValue
    -- is expected to match with the Switch.normalOpen.
    "normalOpen" INTEGER NOT NULL DEFAULT 1 CHECK ("normalOpen" IN (0, 1)),
    -- Usage of switch as a boundary device across persistent connectivity areas,
    -- such as across a transmission-distribution boundary
    -- FK column reference to table representing the "TopologicalUsageKind" enumeration
    "topologicalUsage" VARCHAR(100)
);

-- Single phase of a multi-phase switch when its attributes might be different
-- per phase.
CREATE TABLE "SwitchPhase"
(
    "mRID" VARCHAR(100) PRIMARY KEY,
    -- Used in cases when no Measurement for the status value is present. If the
    -- SwitchPhase has a status measurement the Discrete.normalValue is expected
    -- to match with this value.
    "normalOpen" INTEGER NOT NULL DEFAULT 1 CHECK ("normalOpen" IN (0, 1)),
    -- Phase of this SwitchPhase on the side with terminal sequence number equal
    -- to 1. Should be a phase contained in that terminal's phases attribute.
    -- FK column reference to table representing the "SinglePhaseKind" enumeration
    "phaseSide1" VARCHAR(100),
    -- Phase of this SwitchPhase on the side with terminal sequence number equal
    -- to 2. Should be a phase contained in that terminal's Terminal.phases attribute.
    -- FK column reference to table representing the "SinglePhaseKind" enumeration
    "phaseSide2" VARCHAR(100),
    -- The switch of the switch phase.
    -- FK column reference to table representing the "Switch" class
    "Switch" VARCHAR(100)
);

-- An electromechanical device that operates with shaft rotating synchronously
-- with the network. It is a single machine operating either as a generator
-- or synchronous condenser or pump.
CREATE TABLE "SynchronousMachine"
(
    "mRID" VARCHAR(100) PRIMARY KEY,
    -- Modes that this synchronous machine can operate in.
    -- FK column reference to table representing the "SynchronousMachineKind" enumeration
    "type" VARCHAR(100)
);

-- Synchronous machine type.
CREATE TABLE "SynchronousMachineKind" ( "name" VARCHAR(100) UNIQUE );
-- Indicates the synchronous machine can operate as a condenser.
INSERT INTO "SynchronousMachineKind" ( "name" ) VALUES ( 'condenser' );
-- Indicates the synchronous machine can operate as a generator.
INSERT INTO "SynchronousMachineKind" ( "name" ) VALUES ( 'generator' );
-- Indicates the synchronous machine can operate as a generator or as a condenser.
INSERT INTO "SynchronousMachineKind" ( "name" ) VALUES ( 'generatorOrCondenser' );
-- Indicates the synchronous machine can operate as a generator or as a condenser
-- or as a motor.
INSERT INTO "SynchronousMachineKind" ( "name" ) VALUES ( 'generatorOrCondenserOrMotor' );
-- Indicates the synchronous machine can operate as a generator or as a motor.
INSERT INTO "SynchronousMachineKind" ( "name" ) VALUES ( 'generatorOrMotor' );
-- Indicates the synchronous machine can operate as a motor.
INSERT INTO "SynchronousMachineKind" ( "name" ) VALUES ( 'motor' );
-- Indicates the synchronous machine can operate as a motor or as a condenser.
INSERT INTO "SynchronousMachineKind" ( "name" ) VALUES ( 'motorOrCondenser' );

-- Mechanism for changing transformer winding tap positions.
CREATE TABLE "TapChanger"
(
    "mRID" VARCHAR(100) PRIMARY KEY
);

-- An AC electrical connection point to a piece of conducting equipment. Terminals
-- are connected at physical connection points called connectivity nodes.
CREATE TABLE "Terminal"
(
    "mRID" VARCHAR(100) PRIMARY KEY,
    -- Represents the normal network phasing condition. If the attribute is missing,
    -- three phases (ABC) shall be assumed, except for terminals of grounding
    -- classes (specializations of EarthFaultCompensator, GroundDisconnector,
    -- and Ground) which will be assumed to be N. Therefore, phase code ABCN is
    -- explicitly declared when needed, e.g. for star point grounding equipment.
    -- The phase code on terminals connecting the same ConnectivityNode or TopologicalNode
    -- as well as for equipment between two terminals shall be consistent.
    -- FK column reference to table representing the "PhaseCode" enumeration
    "phases" VARCHAR(100),
    -- FK column reference to table representing the "MultiCircuitGroup" class
    "AdditionalCircuitGroup" VARCHAR(100),
    -- The persistent connectivity-based containment for which the Terminal serves
    -- as a boundary
    -- FK column reference to table representing the "ConnectedArea" class
    "BoundedConnectivityArea" VARCHAR(100),
    -- The conducting equipment of the terminal. Conducting equipment have terminals
    -- that may be connected to other conducting equipment terminals via connectivity
    -- nodes or topological nodes.
    -- FK column reference to table representing the "ConductingEquipment" class
    "ConductingEquipment" VARCHAR(100),
    -- The connectivity node to which this terminal connects with zero impedance.
    -- FK column reference to table representing the "ConnectivityNode" class
    "ConnectivityNode" VARCHAR(100),
    -- The feeder that this terminal normally feeds. Only specified for the terminals
    -- at head of feeders.
    -- FK column reference to table representing the "Feeder" class
    "NormalHeadFeeder" VARCHAR(100),
    -- FK column reference to table representing the "MultiCircuitGroup" class
    "ReferencedCircuitGroup" VARCHAR(100),
    -- The topological node associated with the terminal. This can be used as
    -- an alternative to the connectivity node path to topological node, thus
    -- making it unnecessary to model connectivity nodes in some cases. Note that
    -- the if connectivity nodes are in the model, this association would probably
    -- not be used as an input specification.
    -- FK column reference to table representing the "TopologicalNode" class
    "TopologicalNode" VARCHAR(100)
);

-- For a detailed substation model a topological node is a set of connectivity
-- nodes that, in the current network state, are connected together through
-- any type of closed switches, including jumpers. Topological nodes change
-- as the current network state changes (i.e., switches, breakers, etc. change
-- state).
-- For a planning model, switch statuses are not used to form topological
-- nodes. Instead they are manually created or deleted in a model builder
-- tool. Topological nodes maintained this way are also called "busses".
CREATE TABLE "TopologicalNode"
(
    "mRID" VARCHAR(100) PRIMARY KEY,
    "busName" VARCHAR(255),
    "busNumber" INTEGER,
    -- The base voltage of the topological node.
    -- FK column reference to table representing the "BaseVoltage" class
    "BaseVoltage" VARCHAR(100),
    -- The connectivity node container to which the topological node belongs.
    -- FK column reference to table representing the "ConnectivityNodeContainer" class
    "ConnectivityNodeContainer" VARCHAR(100)
);

-- Usage of switch as a boundary device across persistent connectivity areas,
-- such as across a transmission-distribution boundary
CREATE TABLE "TopologicalUsageKind" ( "name" VARCHAR(100) UNIQUE );
INSERT INTO "TopologicalUsageKind" ( "name" ) VALUES ( 'acrossArea' );
-- Denotes a bus tie switch in a transmission substation. May require Switch.Retained
-- be set to True.
INSERT INTO "TopologicalUsageKind" ( "name" ) VALUES ( 'busTie' );
-- Denotes a bypass switch in a transmission substation, either for maintenance
-- or to bypass a SeriesCompensator. May require Switch.Retained be set to
-- True.
INSERT INTO "TopologicalUsageKind" ( "name" ) VALUES ( 'bypass' );

-- A power systems analysis model construct of one side of a transformer combining
-- the winding and lugs. The transformer end is used to link a side of a power
-- transformer with its associated terminal and connectivity node for use
-- within a star or mesh model.
CREATE TABLE "TransformerEnd"
(
    "mRID" VARCHAR(100) PRIMARY KEY,
    -- Number for this transformer end, corresponding to the end's order in the
    -- power transformer vector group or phase angle clock number. Highest voltage
    -- winding should be 1. Each end within a power transformer should have a
    -- unique subsequent end number. Note the transformer end number need not
    -- match the terminal sequence number.
    "endNumber" INTEGER,
    -- Used only for Yn and Zn connections indicated by PowerTransformerEnd.connectionKind.
    -- If true, the neutral is grounded and attributes TransformerEnd.rground
    -- and TransformerEnd.xground are required. If false, the attributes TransformerEnd.rground
    -- and TransformerEnd.xground are not considered.
    "grounded" INTEGER NOT NULL DEFAULT 1 CHECK ("grounded" IN (0, 1)),
    -- Base voltage of the transformer end. This is essential for PU calculation.
    -- FK column reference to table representing the "BaseVoltage" class
    "BaseVoltage" VARCHAR(100),
    -- Phase tap changer associated with this transformer end.
    -- FK column reference to table representing the "PhaseTapChanger" class
    "PhaseTapChanger" VARCHAR(100),
    -- Ratio tap changer associated with this transformer end.
    -- FK column reference to table representing the "RatioTapChanger" class
    "RatioTapChanger" VARCHAR(100),
    -- Terminal of the power transformer to which this transformer end belongs.
    -- FK column reference to table representing the "Terminal" class
    "Terminal" VARCHAR(100)
);

-- An external physical connection point of a transformer to which a wire,
-- elbow, or other conductor is attached to energize the windings within the
-- transformer tank. A separate TransformerLug is defined for each high voltage
-- bushing and low-voltage lug with appropriate sequence designation specified
-- in accordance with IEEE c57.12.70-2020.
CREATE TABLE "TransformerLug"
(
    "mRID" VARCHAR(100) PRIMARY KEY,
    -- The sequence designation string of a physical transformer terminal, specified
    -- in accordance with IEEE c57.12.70-2020.
    -- The high-side bushing of a transformer is designated HV or H with a sequence
    -- number (i.e. H1, H2, H3). When multiple physical terminals supply the same
    -- winding (e.g. a loop feed transformer), then additional letter is used
    -- (i.e. H1A and H1B).
    -- The low-side terminal is designated LV or X. Polarity is generally subtractive
    -- (i.e. X1, X2, X3) except for single-phase transformers under 200kVA and
    -- 8660V, which use additive polarity (X3, X2, X1).
    -- Three-winding and four-winding transformers receive designations of Y and
    -- Z or as described in IEEE c57.18.10-1998.
    "designation" VARCHAR(255),
    -- The autotransformer winding for which this lug is the second line-side
    -- terminal, connected at the tap or junction of the winding (e.g. X1 on an
    -- autotransformer or L on a step voltage regulator).
    -- FK column reference to table representing the "TransformerWinding" class
    "AutoTransformerWinding" VARCHAR(100),
    -- The winding for which this end is seen as the "from" lug
    -- FK column reference to table representing the "TransformerWinding" class
    "FromTransformerWinding" VARCHAR(100),
    -- The winding for which this end is seen as the "to" lug
    -- FK column reference to table representing the "TransformerWinding" class
    "ToTransformerWinding" VARCHAR(100),
    -- The mathematical TransformerEnd corresponding to the physical terminal
    -- lug
    -- FK column reference to table representing the "TransformerEnd" class
    "TransformerEnd" VARCHAR(100),
    -- The transformer tank to which the lug is attached
    -- FK column reference to table representing the "TransformerTank" class
    "TransformerTank" VARCHAR(100)
);

-- The single-phase aggregation of physical lugs and jumpers on one side of
-- a power transformer (composed of one or more transformer tanks) from the
-- perspective of connectivity to the external network.
-- The end number of each transformer phase end should match the end number
-- of the power transformer end that is connected to the same Terminal such
-- that phase ends on one side of the transformer all carry the same end number.
-- The total number of phase ends should match the total number of phases
-- of that side of the transformer, as indicated by the phase code of the
-- terminal. For example, the low side of an open-wye/open-delta transformer
-- with 4-wire ABCN service will have four transformer phase ends.
CREATE TABLE "TransformerPhaseEnd"
(
    "mRID" VARCHAR(100) PRIMARY KEY,
    -- The single phase of the aggregation of all lugs connected together to form
    -- the terminal-facing connection on this side of the transformer.
    -- FK column reference to table representing the "SinglePhaseKind" enumeration
    "phase" VARCHAR(100),
    -- The no-load voltage of this single phase relative to the neutral of the
    -- connected end. It is the phase-to-neutral voltage, which is not necessarily
    -- equal to the phase-to-phase rated voltage divided by v3.
    -- For example, a 12470 V wye primary has 7200 V on each phase, a 120/240
    -- V split-phase secondary has 120 V on s1 and on s2, and the high leg of
    -- a open-delta secondary has a no-load voltage of about 208 V. The neutral
    -- phase end (N) has a value of 0 V.
    "phaseNeutralU" DOUBLE PRECISION,
    -- The position of this phase end among the phase ends of its transformer
    -- end, starting at 1. The order should match the order of the phases in the
    -- associated Terminal�s phases, with the neutral last.
    -- For example, a terminal with phases BN is sequenced B=1, N=2, and a terminal
    -- with phases s1s2N is sequenced s1=1, s2=2, N=3. A phase end is identified
    -- within the transformer by the combination of its end number and sequence
    -- number.
    "sequenceNumber" INTEGER
);

-- An assembly of two or more coupled windings that transform electrical power
-- between voltage levels. These windings are bound on a common core and placed
-- in the same tank. Transformer tank can be used to model both single-phase
-- and 3-phase transformers.
CREATE TABLE "TransformerTank"
(
    "mRID" VARCHAR(100) PRIMARY KEY,
    -- Bank this transformer belongs to.
    -- FK column reference to table representing the "PowerTransformer" class
    "PowerTransformer" VARCHAR(100)
);

-- The assembly of turns forming an electric circuit associated with one of
-- the voltages assigned to the transformer [source: IEV 421-03-01]
-- Winding polarity is expressed by which lug / end is designated "from" and
-- which is the "to" lug / end. Windings with the same polarity convention
-- have from lugs that are instantaneously in phase. Subtractive polarity
-- has H1 and X1 as from lugs. Additive polarity has H1 and X3 as from lugs.
-- The associations, not the lug designation strings should be used to determine
-- polarity.
CREATE TABLE "TransformerWinding"
(
    "mRID" VARCHAR(100) PRIMARY KEY,
    -- Denotes whether winding is intended to be connected phase-to-phase or phase-to-neutral.
    -- FK column reference to table representing the "PhaseShuntConnectionKind" enumeration
    "connection" VARCHAR(100),
    -- The TransformerLug at the tap or junction of an autotransformer winding,
    -- where the winding connects to the second line-side terminal. Examples are
    -- X1 on an autotransformer and L on a step voltage regulator. This lug is
    -- identified by its position on the winding, not by whether it is the source
    -- or the load side, which depends on power flow.
    -- FK column reference to table representing the "TransformerLug" class
    "AutoTransformerLug" VARCHAR(100),
    -- The transformer end that aggregates the winding's from lug (or lugs). It
    -- is the point where the polarity-marked side of the winding connects to
    -- the power system model. Absent when the from lug is not connected to a
    -- terminal-facing end, such as an internal junction. For balanced three-phase
    -- transformers, this is the only end that needs to be specified. For unbalanced
    -- per-tank modeling, the "from" and "to" need to be specified.
    -- FK column reference to table representing the "TransformerEnd" class
    "FromTransformerEnd" VARCHAR(100),
    -- The lug at the polarity-marked end of the winding. When this lug is instantaneously
    -- positive, the opposite end of the winding (the "to" lug) is instantaneously
    -- negative. This is not necessarily the lug with the lowest designation number.
    -- For example, H1 is the from lug of a primary winding, and X1 is the from
    -- lug of a secondary winding with subtractive polarity. For a center-tapped
    -- split-phase tank with additive polarity, the from lug of the secondary
    -- is X3 for the winding X3�X2, and X2 for the winding X2�X1.
    -- FK column reference to table representing the "TransformerLug" class
    "FromTransformerLug" VARCHAR(100),
    -- The transformer end that aggregates the winding's to lug. It is the point
    -- where the opposite side of the winding connects to the power system model.
    -- Absent when the to lug is not connected to a terminal-facing end, such
    -- as the unused center tap X2 on a winding pair connected only at X1 and
    -- X3.
    -- FK column reference to table representing the "TransformerEnd" class
    "ToTransformerEnd" VARCHAR(100),
    -- The transformer lug at the end of the winding opposite the polarity-marked
    -- end, which is the return terminal for current entering at the "from" lug.
    -- For example, the "to" lug is H2 on a primary winding. For a secondary winding
    -- on a split-phase center-tapped tank with additive polarity, it is X2 for
    -- the winding X3�X2 and X1 for the winding X2�X1. For an autotransformer
    -- or step voltage regulator winding, this is the common lug shared by both
    -- sides (e.g. H0X0 or SL).
    -- FK column reference to table representing the "TransformerLug" class
    "ToTransformerLug" VARCHAR(100),
    -- The transformer tank in which the winding is contained
    -- FK column reference to table representing the "TransformerTank" class
    "TransformerTank" VARCHAR(100)
);

-- Internal configuration code of a set of three-phase windings, as defined
-- in IEC 60076-1 / IEEE c57.12.70-2021
CREATE TABLE "WindingConfigurationKind" ( "name" VARCHAR(100) UNIQUE );
-- D1, also known as D_AB
INSERT INTO "WindingConfigurationKind" ( "name" ) VALUES ( 'D1' );
-- D11, also known as D_AC
INSERT INTO "WindingConfigurationKind" ( "name" ) VALUES ( 'D11' );
INSERT INTO "WindingConfigurationKind" ( "name" ) VALUES ( 'D3' );
INSERT INTO "WindingConfigurationKind" ( "name" ) VALUES ( 'D5' );
INSERT INTO "WindingConfigurationKind" ( "name" ) VALUES ( 'D7' );
INSERT INTO "WindingConfigurationKind" ( "name" ) VALUES ( 'D9' );
INSERT INTO "WindingConfigurationKind" ( "name" ) VALUES ( 'Y0' );
INSERT INTO "WindingConfigurationKind" ( "name" ) VALUES ( 'Y10' );
INSERT INTO "WindingConfigurationKind" ( "name" ) VALUES ( 'Y2' );
INSERT INTO "WindingConfigurationKind" ( "name" ) VALUES ( 'Y4' );
INSERT INTO "WindingConfigurationKind" ( "name" ) VALUES ( 'Y6' );
INSERT INTO "WindingConfigurationKind" ( "name" ) VALUES ( 'Y8' );
INSERT INTO "WindingConfigurationKind" ( "name" ) VALUES ( 'Z11AC' );
INSERT INTO "WindingConfigurationKind" ( "name" ) VALUES ( 'Z1AB' );
INSERT INTO "WindingConfigurationKind" ( "name" ) VALUES ( 'Z5AC' );
INSERT INTO "WindingConfigurationKind" ( "name" ) VALUES ( 'Z7AB' );

-- Winding connection type.
CREATE TABLE "WindingConnection" ( "name" VARCHAR(100) UNIQUE );
-- Autotransformer common winding.
INSERT INTO "WindingConnection" ( "name" ) VALUES ( 'A' );
-- Delta.
INSERT INTO "WindingConnection" ( "name" ) VALUES ( 'D' );
INSERT INTO "WindingConnection" ( "name" ) VALUES ( 'Dn' );
-- Independent winding, for single-phase connections.
INSERT INTO "WindingConnection" ( "name" ) VALUES ( 'I' );
INSERT INTO "WindingConnection" ( "name" ) VALUES ( 'T' );
-- Wye.
INSERT INTO "WindingConnection" ( "name" ) VALUES ( 'Y' );
-- Wye, with neutral brought out for grounding.
INSERT INTO "WindingConnection" ( "name" ) VALUES ( 'Yn' );
-- ZigZag.
INSERT INTO "WindingConnection" ( "name" ) VALUES ( 'Z' );
-- ZigZag, with neutral brought out for grounding.
INSERT INTO "WindingConnection" ( "name" ) VALUES ( 'Zn' );
INSERT INTO "WindingConnection" ( "name" ) VALUES ( 'oD' );
INSERT INTO "WindingConnection" ( "name" ) VALUES ( 'oY' );

-- A two terminal and power conducting device of negligible impedance and
-- length represented as zero impedance device that can be used to connect
-- auxiliary equipment to its terminals.
CREATE TABLE "WireSegment"
(
    "mRID" VARCHAR(100) PRIMARY KEY
);

-- Represents a single wire of an alternating current wire segment.
CREATE TABLE "WireSegmentPhase"
(
    "mRID" VARCHAR(100) PRIMARY KEY,
    -- The phase connection of the wire at both ends.
    -- FK column reference to table representing the "SinglePhaseKind" enumeration
    "phase" VARCHAR(100),
    -- Number designation for this wire segment phase. Each wire segment phase
    -- within a wire segment should have a unique sequence number.
    "sequenceNumber" INTEGER,
    -- The wire segment to which the phase belongs.
    -- FK column reference to table representing the "WireSegment" class
    "WireSegment" VARCHAR(100)
);

